CREATE TEMP TABLE t3(e,f); CREATE TEMP TABLE log(op,x,y); CREATE TEMP TRIGGER t3r1 AFTER DELETE ON t3 BEGIN INSERT INTO log VALUES('D3',old.e,old.f); END; CREATE TEMP TRIGGER t3r2 BEFORE UPDATE ON t3 BEGIN INSERT INTO log VALUES('U3',new.e,new.f); END; INSERT INTO t3(e) VALUES(1),(2),(3) RETURNING 'I',e; UPDATE t3 SET f=e+100 RETURNING 'U',e,f; DELETE FROM t3 WHERE f>100 RETURNING 'D',e,f; CREATE TABLE main.capture AS SELECT op,x,y FROM temp.log;